  1	import type { CalculatorRpcClientError } from "@taxkit/api-rpc/errors";
  2	import { TaxKitRpcClientLive } from "@taxkit/api-rpc/live";
  3	import type {
  4	  CalculatorCatalogResponse,
  5	  CalculatorRunResponse,
  6	  CalculatorRunServiceRequest,
  7	} from "@taxkit/api-rpc/schemas";
  8	import { TaxKitRpcClient } from "@taxkit/api-rpc/service";
  9	import { AnnualTaxReport } from "@taxkit/rules-au-income-tax/schemas";
 10	import {
 11	  AuPayCalculatorId,
 12	  PayWithholdingsLedger,
 13	  TakeHomePayReport,
 14	} from "@taxkit/rules-au-pay/schemas";
 15	import { Cause, Effect, Layer, Match, Option, Result, Schema } from "effect";
 16	import { FetchHttpClient } from "effect/http";
 17	import * as AsyncResult from "effect/reactivity/AsyncResult";
 18	import * as Atom from "effect/reactivity/Atom";
 19	
 20	import { calculationFailureMessage } from "./calculation-failure";
 21	import { BrowserCalculatorPolicyLive } from "./calculator-policy.browser.layer";
 22	import { TaxKitWebConfigError } from "./config";
 23	import {
 24	  takeHomeRequestFromForm,
 25	  annualTaxRequestFromForm,
 26	  initialTakeHomeForm,
 27	  AnnualTaxForm,
 28	  WebsiteInputError,
 29	  TakeHomeForm,
 30	} from "./form.boundary";
 31	import type { WebsiteCalculatorForm } from "./form.boundary";
 32	import type {
 33	  WebsiteCalculatorViewState,
 34	  WebsitePublicSettings,
 35	} from "./schemas";
 36	
 37	// These are descriptions of work. React's registry owns client acquisition,
 38	// execution and release; no module creates or runs a browser ManagedRuntime.
 39	// The loader seeds these settings for the React registry's whole lifetime.
 40	// They must survive an idle form before its first calculation.
 41	export const publicSettingsAtom = Atom.make(
 42	  Option.none<WebsitePublicSettings>()
 43	).pipe(Atom.keepAlive);
 44	export const websiteCatalogueAtom = Atom.make(
 45	  Option.none<CalculatorCatalogResponse>()
 46	).pipe(Atom.keepAlive);
 47	export const calculatorRuntime = Atom.runtime((get) =>
 48	  Option.match(get(publicSettingsAtom), {
 49	    onNone: () =>
 50	      Layer.effect(
 51	        TaxKitRpcClient,
 52	        Effect.fail(
 53	          new TaxKitWebConfigError({
 54	            message: "TaxKit web settings are missing or invalid.",
 55	            operation: "settings",
 56	            runtime: "client",
 57	          })
 58	        )
 59	      ),
 60	    onSome: (settings) =>
 61	      TaxKitRpcClientLive(settings.apiOrigin).pipe(
 62	        Layer.provide(
 63	          BrowserCalculatorPolicyLive.pipe(Layer.provide(FetchHttpClient.layer))
 64	        )
 65	      ),
 66	  })
 67	);
 68	// The registry owns separate temporary state for each checked calculator ID.
 69	// The family memoises descriptions, never a client or a computed answer.
 70	export const calculatorPageAtoms = Atom.family(
 71	  (calculatorId: CalculatorRunServiceRequest["calculatorId"]) => {
 72	    const form = Atom.make<WebsiteCalculatorForm>(
 73	      Match.value(calculatorId).pipe(
 74	        Match.when("au.income-tax.annual", () =>
 75	          AnnualTaxForm.make({ taxableDollars: "67000" })
 76	        ),
 77	        Match.when("au.pay.take-home", () => initialTakeHomeForm),
 78	        Match.orElse(() => ({
 79	          grossDollars: "9500",
 80	          period: "monthly",
 81	          taxFreeThresholdClaimed: false,
 82	        }))
 83	      )
 84	    );
 85	    const calculation = calculatorRuntime.fn<CalculatorRunServiceRequest>()(
 86	      (request) =>
 87	        TaxKitRpcClient.pipe(
 88	          Effect.flatMap((client) => client.calculate(request))
 89	        )
 90	    );
 91	    const showSaved = Atom.make(true);
 92	    const showCalculation = Atom.make(false);
 93	    const formError = Atom.make(Option.none<string>());
 94	    const savedReport = Atom.make(
 95	      Option.none<CalculatorRunResponse["report"]>()
 96	    );
 97	    const savedMessage = Atom.make(Option.none<string>());
 98	    // Checked request identity belongs to one visible attempt. An edit or a
 99	    // newer manual/tool submission invalidates a waiter for the older attempt.
100	    const attempt = Atom.make(Option.none<CalculatorRunServiceRequest>());
101	    const cancel = Atom.fnSync<"cancel">()((_, get) => {
102	      get.set(attempt, Option.none());
103	      get.set(calculation, Atom.Interrupt);
104	      get.set(showCalculation, false);
105	    });
106	    const edit = Atom.fnSync<WebsiteCalculatorForm>()((value, get) => {
107	      get.set(attempt, Option.none());
108	      get.set(calculation, Atom.Interrupt);
109	      get.set(showCalculation, false);
110	      get.set(showSaved, false);
111	      get.set(formError, Option.none());
112	      get.set(form, value);
113	    });
114	    const submit = Atom.fnSync<"calculate">()((_, get) => {
115	      const current = get(form);
116	      const request = Result.gen(function* () {
117	        if (calculatorId === "au.income-tax.annual") {
118	          return yield* "taxableDollars" in current
119	            ? annualTaxRequestFromForm(current)
120	            : Result.fail(
121	                new WebsiteInputError({
122	                  message: "Enter a valid annual taxable income.",
123	                })
124	              );
125	        }
126	        return yield* "grossDollars" in current
127	          ? takeHomeRequestFromForm(
128	              current,
129	              AuPayCalculatorId.make(calculatorId)
130	            )
131	          : Result.fail(
132	              new WebsiteInputError({
133	                message: "Enter a valid pay amount and pay period.",
134	              })
135	            );
136	      });
137	      get.set(showCalculation, true);
138	      get.set(showSaved, false);
139	      if (Result.isFailure(request)) {
140	        get.set(attempt, Option.none());
141	        get.set(calculation, Atom.Interrupt);
142	        get.set(formError, Option.some(request.failure.message));
143	        return;
144	      }
145	      get.set(formError, Option.none());
146	      get.set(attempt, Option.some(request.success));
147	      get.set(calculation, request.success);
148	    });
149	    const group = {
150	      attempt,
151	      calculation,
152	      cancel,
153	      edit,
154	      form,
155	      formError,
156	      savedMessage,
157	      savedReport,
158	      showCalculation,
159	      showSaved,
160	      submit,
161	      // The registry retains this in-memory page snapshot across an uncommitted
162	      // React render. Otherwise idle cleanup can erase once-seeded SSR values
163	      // before hydration subscribes. Page cleanup still interrupts live work.
164	      // The retained view also holds its whole weak-family description group.
165	      // Otherwise browser GC can replace that group on a return visit while the
166	      // old values remain in the registry. The callback runs after group creation.
167	      // Disposing the root registry releases the snapshot and its client.
168	      view: Atom.make((get): WebsiteCalculatorViewState => {
169	        const current = get(calculation);
170	        const submitted = get(showCalculation);
171	        const saved = get(showSaved);
172	        const inputError = get(formError);
173	        const report = AsyncResult.value(current).pipe(
174	          Option.filter(
175	            (value) => value.calculator.calculatorId === calculatorId
176	          ),
177	          Option.map((value) => value.report),
178	          Option.orElse(() => get(savedReport)),
179	          Option.filter((value) =>
180	            Match.value(calculatorId).pipe(
181	              Match.when("au.income-tax.annual", () =>
182	                Schema.is(AnnualTaxReport)(value)
183	              ),
184	              Match.when("au.pay.take-home", () =>
185	                Schema.is(TakeHomePayReport)(value)
186	              ),
187	              Match.orElse(() => Schema.is(PayWithholdingsLedger)(value))
188	            )
189	          )
190	        );
191	        const message = Option.match(inputError, {
192	          onNone: () => {
193	            if (
194	              submitted &&
195	              !current.waiting &&
196	              (AsyncResult.isFailure(current) ||
197	                (AsyncResult.isSuccess(current) && Option.isNone(report)))
198	            ) {
199	              if (AsyncResult.isFailure(current)) {
200	                return current.cause.pipe(
201	                  Cause.findErrorOption,
202	                  Option.map(calculationFailureMessage)
203	                );
204	              }
205	              return Option.some(
206	                "The calculation could not finish. Please try again."
207	              );
208	            }
209	            return saved ? get(savedMessage) : Option.none<string>();
210	          },
211	          onSome: Option.some,
212	        });
213	        return {
214	          busy: submitted && current.waiting,
215	          calculatorId,
216	          form: get(group.form),
217	          message,
218	          report,
219	          stale:
220	            Option.isSome(report) &&
221	            !saved &&
222	            (!submitted ||
223	              current.waiting ||
224	              !AsyncResult.isSuccess(current) ||
225	              Option.isSome(inputError)),
226	        };
227	      }).pipe(Atom.keepAlive),
228	    } as const;
229	    return group;
230	  }
231	);
232	
233	// Home uses the same page commands and state owner as the other calculators.
234	// These existing names retain their narrow React/test call sites.
235	const home = calculatorPageAtoms(AuPayCalculatorId.make("au.pay.take-home"));
236	export const calculateAtom: Atom.AtomResultFn<
237	  CalculatorRunServiceRequest,
238	  CalculatorRunResponse,
239	  CalculatorRpcClientError | TaxKitWebConfigError
240	> = home.calculation;
241	export const takeHomeFormAtom = Atom.writable(
242	  (get) => {
243	    const form = get(home.form);
244	    return Schema.is(TakeHomeForm)(form) ? form : initialTakeHomeForm;
245	  },
246	  (get, form: TakeHomeForm) => get.set(home.form, form)
247	);
248	export const submitTakeHomeAtom = home.submit;
249	export const editTakeHomeAtom = Atom.fnSync<TakeHomeForm>()((value, get) =>
250	  get.set(home.edit, value)
251	);

