  6	import { Content } from "@common-practice/content/service";
  7	import type { PageId, PageInput } from "@common-practice/content/schemas";
  8	import {
  9	  applyResponsePolicy,
 10	  responsePolicyHeaders,
 11	} from "@common-practice/http/publishing-policy";
 12	import type { ResponsePolicyRequest } from "@common-practice/http/publishing-policy";
 13	import { IsolateIdentityLive } from "@common-practice/infrastructure/runtime/isolate-identity";
 14	import * as Effect from "effect/Effect";
 15	import * as Layer from "effect/Layer";
 16	import * as Logger from "effect/Logger";
 17	import * as ManagedRuntime from "effect/ManagedRuntime";
 18	import * as Option from "effect/Option";
