 40	import { discoveryRepresentation } from "./http/discovery.ingress";
 41	import { CaptureRelayLive } from "./analytics/relay/live.layer";
 42	import { captureRelayRequest } from "./analytics/relay/request.ingress";
 43	import { readCourses, readCourse, readTrainingPage } from "./training/load.egress";
 44	import { CourseLoadResult, trainingFailureStatus } from "./training/page.egress";
 45	import type { CourseListLoadResult, TrainingPageLoadResult } from "./training/page.egress";
 46	import * as Match from "effect/Match";
 47	import { trainingRepresentation } from "./training/representation.ingress";
 48	import { readCourseRequest, readTrainingPageRequest } from "./training/request.ingress";
 49	import type { InvalidTrainingRequestError } from "@common-practice/training/errors";
 50	import {
 51	  hasAppearanceCookie,
 52	  readAppearanceCookie,
 53	} from "@common-practice/appearance/cookie-reader";
 54	import { readAppearanceCookieHeader } from "@common-practice/appearance/input";
 55	import { appearanceOptions } from "./appearance/settings";
 56	
 57	const rejectedTrainingRequest = Effect.fnUntraced(function* (failure: InvalidTrainingRequestError) {
 58	  return yield* Schema.encodeEffect(CourseLoadResult.cases.TrainingLoadFailed)(
 59	    CourseLoadResult.cases.TrainingLoadFailed.make({ error: failure }),
 60	  );
 61	});
 62	
 63	const setTrainingFailureStatus = (
 64	  result:
 65	    | typeof CourseLoadResult.Encoded
 66	    | typeof CourseListLoadResult.Encoded
 67	    | typeof TrainingPageLoadResult.Encoded,
 68	) =>
 69	  Match.value(result).pipe(
 70	    Match.tag("TrainingLoadFailed", ({ error }) => {
 71	      const status = trainingFailureStatus(error);
 72	      return Effect.sync(() => {
 73	        setResponseStatus(status);
 74	      });
 75	    }),
 76	    Match.orElse(() => Effect.void),
 77	  );
 78	
 79	const application = Layer.mergeAll(
 80	  Logger.layer([Logger.consoleJson]),
 81	  ApiClientsLive.pipe(Layer.provideMerge(WebsiteApiLive)),
 82	  CaptureRelayLive.pipe(
 83	    Layer.provide(
 84	      FetchHttpClient.layer.pipe(
 85	        Layer.provide(Layer.succeed(FetchHttpClient.RequestInit, { redirect: "manual" })),
 86	      ),
 87	    ),
 88	  ),
 89	  IsolateIdentityLive.pipe(Layer.provide(NodeCrypto.layer)),
 90	);
 91	type ApplicationServices = Layer.Success<typeof application>;
 92	
 93	// TanStack owns this one frontend runtime. It supplies clients, never backend implementations.
 94	const runtime = ManagedRuntime.make(application);
 95	const runForRequest = <A, E>({
 96	  effect,
 97	  signal,
 98	}: {
 99	  readonly effect: Effect.Effect<A, E, ApplicationServices>;
100	  readonly signal?: AbortSignal;
101	}) => runtime.runPromise(effect, { signal });
102	
103	export const handleCaptureRelayRequest = ({ request }: { readonly request: Request }) =>
104	  runForRequest({
105	    effect: captureRelayRequest.pipe(
106	      Effect.provideService(
107	        HttpServerRequest.HttpServerRequest,
108	        HttpServerRequest.fromWeb(request),
109	      ),
110	      Effect.map((response) =>
111	        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
112	      ),
113	    ),
114	    signal: request.signal,
115	  });
116	
117	export const handleMachineRequest = ({ request }: { readonly request: Request }) =>
118	  runForRequest({
119	    effect: WebsiteApi.pipe(
120	      Effect.flatMap((api) => api.forward(HttpServerRequest.fromWeb(request))),
121	      Effect.catchTag("ApiBindingError", () =>
122	        Effect.succeed(
123	          applyResponsePolicy({
124	            request: { adapter: "machine", method: request.method, pathname: Option.none() },
125	            response: HttpServerResponse.empty({ status: 503 }),
126	          }),
127	        ),
128	      ),
129	      Effect.map((response) =>
130	        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
131	      ),
132	    ),
133	    signal: request.signal,
134	  });
135	
136	export const handlePageRepresentation = ({
137	  request,
138	  id,
139	  format,
140	}: {
141	  readonly request: Request;
142	  readonly id: PageId;
143	  readonly format: "markdown" | "og";
144	}) =>
145	  runForRequest({
146	    effect: pageRepresentation({
147	      method: HttpServerRequest.fromWeb(request).method,
148	      id,
149	      format,
150	    }).pipe(
151	      Effect.map((response) =>
152	        HttpServerResponse.toWeb(
153	          applyResponsePolicy({
154	            request: {
155	              adapter: "machine",
156	              method: request.method,
157	              pathname: Url.fromString(request.url).pipe(
158	                Result.getSuccess,
159	                Option.map((url) => url.pathname),
160	              ),
161	            },
162	            response,
163	          }),
164	          { withoutBody: request.method === "HEAD" },
165	        ),
166	      ),
167	    ),
168	    signal: request.signal,
169	  });
170	
171	// Encode before leaving the runtime; TanStack serialises these plain objects without losing tags.
172	export const loadPage = ({
173	  input,
174	  signal,
175	}: {
176	  readonly input: PageInput;
177	  readonly signal: AbortSignal;
178	}) =>
179	  runForRequest({
180	    effect: Content.pipe(
181	      Effect.flatMap((content) => content.getPage({ id: input.id })),
182	      Effect.matchEffect({
183	        onSuccess: ({ page }) =>
184	          Schema.encodeEffect(PageLoadResult)(PageLoadResult.cases.PageLoaded.make({ page })),
185	        onFailure: (error) =>
186	          Effect.sync(() => {
187	            const status = pageFailureStatus(error);
188	            setResponseStatus(status);
189	          }).pipe(
190	            Effect.flatMap(() =>
191	              Schema.encodeEffect(PageLoadResult)(
192	                PageLoadResult.cases.PageLoadFailed.make({ error }),
193	              ),
194	            ),
195	          ),
196	      }),
197	    ),
198	    signal,
199	  });
200	
201	export const loadWebsiteConfig = ({ request }: { readonly request: Request }) =>
202	  runForRequest({
203	    effect: Effect.gen(function* () {
204	      const header = yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
205	        Effect.flatMap(readAppearanceCookieHeader),
206	      );
207	      const appearance = yield* readAppearanceCookie(header, appearanceOptions);
208	      return yield* WebsiteApi.pipe(
209	        Effect.flatMap((api) => api.configuration),
210	        Effect.matchEffect({
211	          onSuccess: (origins) =>
212	            Schema.encodeEffect(WebsiteConfig)(
213	              WebsiteConfig.cases.WebsiteConfigured.make({ ...origins, appearance }),
214	            ),
215	          onFailure: () =>
216	            Schema.encodeEffect(WebsiteConfig)(
217	              WebsiteConfig.cases.WebsiteUnavailable.make({ appearance }),
218	            ),
219	        }),
220	      );
221	    }),
222	    signal: request.signal,
223	  });
224	
225	export const loadCourses = ({ signal }: { readonly signal: AbortSignal }) =>
226	  runForRequest({
227	    effect: readCourses.pipe(Effect.tap(setTrainingFailureStatus)),
228	    signal,
229	  });
230	export const loadCourse = ({
231	  input,
232	  signal,
233	}: Readonly<{ input: Schema.Json; signal: AbortSignal }>) =>
234	  runForRequest({
235	    effect: readCourseRequest(input).pipe(
236	      Effect.flatMap(readCourse),
237	      Effect.catchTag("InvalidTrainingRequestError", rejectedTrainingRequest),
238	      Effect.tap(setTrainingFailureStatus),
239	    ),
240	    signal,
241	  });
242	export const loadTrainingPage = ({
243	  input,
244	  signal,
245	}: Readonly<{ input: Schema.Json; signal: AbortSignal }>) =>
246	  runForRequest({
247	    effect: readTrainingPageRequest(input).pipe(
248	      Effect.flatMap(readTrainingPage),
