272	            Effect.flatMap((api) => api.stage),
273	            Effect.map((stage) => stage === "production"),
274	            Effect.orElseSucceed(() => false),
275	          ),
276	        };
277	        const selected = yield* discoveryRepresentation.pipe(
278	          Effect.flatMap((discovery) =>
279	            Option.match(discovery, {
280	              onNone: () => trainingRepresentation,
281	              onSome: Effect.succeedSome,
