  1	import { Content } from "@common-practice/content/service";
  2	import { ApiRoutes } from "@common-practice/http/server";
  3	import { applyResponsePolicy, requestPathname } from "@common-practice/http/publishing-policy";
  4	import { mcpRoutes } from "@common-practice/mcp/server";
  5	import { isPublicMcpOrigin } from "@common-practice/mcp/schemas";
  6	import { RpcRoutes } from "@common-practice/rpc/server";
  7	import * as Boolean from "effect/Boolean";
  8	import * as Context from "effect/Context";
  9	import * as Deferred from "effect/Deferred";
 10	import * as Effect from "effect/Effect";
 11	import * as ErrorReporter from "effect/ErrorReporter";
 12	import * as Layer from "effect/Layer";
 13	import * as Option from "effect/Option";
 14	import type * as Scope from "effect/Scope";
 15	import * as HttpEffect from "effect/http/HttpEffect";
 16	import * as Headers from "effect/http/Headers";
 17	import * as HttpRouter from "effect/http/HttpRouter";
 18	import * as HttpServerError from "effect/http/HttpServerError";
 19	import * as HttpServerRequest from "effect/http/HttpServerRequest";
 20	import * as HttpServerResponse from "effect/http/HttpServerResponse";
 21	import { publishingRoutes } from "../aeo/routes.egress";
 22	import { agentSkillsRoutes } from "../aeo/agent-skills.egress";
 23	
 24	export class ApiHandler extends Context.Service<
 25	  ApiHandler,
 26	  {
 27	    readonly http: Effect.Effect<
 28	      HttpServerResponse.HttpServerResponse,
 29	      never,
 30	      HttpServerRequest.HttpServerRequest | Scope.Scope
 31	    >;
 32	  }
 33	>()("common-practice/ApiHandler") {}
 34	
 35	// All native transports call Content. They share its isolate lifetime, while each
 36	// incoming request keeps its own fibre, cancellation signal and response scope.
 37	export const apiHandlerLayer = Layer.effect(
 38	  ApiHandler,
 39	  Effect.gen(function* () {
 40	    const routes = Layer.mergeAll(
 41	      ApiRoutes,
 42	      RpcRoutes,
 43	      mcpRoutes,
 44	      publishingRoutes,
 45	      agentSkillsRoutes,
 46	      HttpRouter.cors({
 47	        allowedOrigins: ["*"],
 48	        allowedMethods: ["GET", "HEAD", "POST", "OPTIONS"],
 49	        allowedHeaders: [
 50	          "content-type",
 51	          "accept",
 52	          // Native Effect clients propagate both tracing formats in browsers.
 53	          "b3",
 54	          "traceparent",
 55	          "mcp-protocol-version",
 56	          "mcp-method",
 57	          "mcp-name",
 58	        ],
 59	        exposedHeaders: ["mcp-protocol-version"],
 60	        credentials: false,
 61	        maxAge: 300,
 62	      }),
 63	    );
 64	    const router = yield* HttpRouter.toHttpEffect(routes);
 65	    const services = Context.pick(Content)(yield* Effect.context<Content>());
 66	    const http = Effect.gen(function* () {
 67	      const request = yield* HttpServerRequest.HttpServerRequest;
 68	      const originHeader = Headers.get(request.headers, "origin");
 69	      // Validate Origin before CORS, including OPTIONS preflight requests.
 70	      const response = yield* Boolean.match(
 71	        Option.exists(originHeader, (value) => !isPublicMcpOrigin(value)),
 72	        {
 73	          onTrue: () => Effect.succeed(HttpServerResponse.empty({ status: 403 })),
 74	          onFalse: () =>
 75	            router.pipe(
 76	              Effect.catchCause((cause) =>
 77	                HttpServerError.causeResponse(cause).pipe(
 78	                  Effect.flatMap(([recovered, reportable]) =>
 79	                    ErrorReporter.report(reportable).pipe(Effect.as(recovered)),
 80	                  ),
 81	                ),
 82	              ),
 83	            ),
 84	        },
 85	      );
 86	      return applyResponsePolicy({
 87	        request: {
 88	          adapter: "machine",
 89	          method: request.method,
 90	          pathname: requestPathname(request),
 91	        },
 92	        response,
 93	      });
 94	    }).pipe(Effect.provideContext(services));
 95	    return ApiHandler.of({ http });
 96	  }),
 97	);
 98	
 99	export const serveResponse = Effect.fnUntraced(function* (
100	  request: HttpServerRequest.HttpServerRequest,
101	) {
102	  const { http } = yield* ApiHandler;
103	  const served = yield* Deferred.make<HttpServerResponse.HttpServerResponse>();
104	  yield* HttpEffect.toHandled(http, (handled, response) =>
105	    Deferred.succeed(
106	      served,
107	      Boolean.match(HttpServerResponse.omitsBody(response, handled.method === "HEAD"), {
108	        onFalse: () => HttpEffect.scopeTransferToStream(response),
109	        onTrue: () => response,
110	      }),
111	    ),
112	  ).pipe(Effect.provideService(HttpServerRequest.HttpServerRequest, request));
113	  return yield* Deferred.await(served);
114	});
115	
116	export const webResponse = Effect.fn("Api.webResponse")(function* (request: Request) {
117	  const serverRequest = HttpServerRequest.fromWeb(request);
118	  const response = yield* serveResponse(serverRequest);
119	  const context = yield* Effect.context();
120	  return HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD", context });
121	});

