 18	
 19	// Keep the host object's identity. Alchemy owns the conversion into Effect.
 20	export const ApiBinding = Schema.declare<Parameters<typeof fromCloudflareFetcher>[0]>(
 21	  (value): value is Parameters<typeof fromCloudflareFetcher>[0] =>
 22	    Predicate.hasProperty(value, "fetch") &&
 23	    Predicate.isFunction(value.fetch) &&
 24	    Predicate.hasProperty(value, "connect") &&
 25	    Predicate.isFunction(value.connect),
 26	);
 27	export const forwardApiRequest = ({
 28	  request,
 29	  binding,
 30	}: {
 31	  readonly request: HttpServerRequest.HttpServerRequest;
 32	  readonly binding: typeof ApiBinding.Type;
 33	}) =>
 34	  fromCloudflareFetcher(binding)
 35	    .fetch(request)
 36	    .pipe(
 37	      // Alchemy reports rejected host Promises as defects. Keep the Website's
 38	      // named transport failure without turning interruption into a response.
 39	      Effect.catchDefect(() => Effect.fail(new ApiBindingError({ operation: "forward" }))),
 40	      Effect.mapError(() => new ApiBindingError({ operation: "forward" })),
 41	    );
 42	
 43	export const readWebsiteConfiguration = Effect.fn("WebsiteApi.configuration")(
 44	  function* ({
 45	    apiUrl,
 46	    websiteUrl,
 47	    capture,
 48	    stage: rawStage,
 49	  }: {
 50	    readonly apiUrl: unknown;
 51	    readonly websiteUrl: unknown;
 52	    readonly capture: unknown;
 53	    readonly stage: unknown;
 54	  }) {
 55	    const bindings = {
 56	      COMMON_PRACTICE_API_URL: apiUrl,
 57	      COMMON_PRACTICE_WEBSITE_URL: websiteUrl,
 58	      COMMON_PRACTICE_POSTHOG_CONFIG: capture,
 59	      COMMON_PRACTICE_STAGE: rawStage,
 60	    };
 61	    // Use the same native Alchemy unwrapping as its Effect Worker host. Only
 62	    // these named settings enter the provider; each Config owns its Schema check.
 63	    const source = ConfigProvider.fromUnknown(bindings);
 64	    const provider = reifyBoundConfigProvider(source, bindings);
 65	    return yield* WebsiteAppConfig.parse(provider);
 66	  },
 67	  Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
 68	);
 69	
 70	// A private binding is an Effect HttpClient transport, rather than a second Content implementation.
 71	export const ApiClientsLive = Layer.unwrap(
 72	  Effect.gen(function* () {
 73	    const api = yield* WebsiteApi;
 74	    const transport = toHttpClient({
 75	      fetch: (request) =>
 76	        api.forward(request).pipe(
 77	          Effect.mapError(
 78	            (cause) =>
 79	              new HttpServerError.HttpServerError({
 80	                reason: new HttpServerError.InternalError({ request, cause }),
 81	              }),
 82	          ),
 83	        ),
 84	    });
 85	    const options = { baseUrl: ApiOrigin.make("https://backend") };
 86	    return Layer.mergeAll(
 87	      contentHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
 88	      trainingHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
 89	    ).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)));
 90	  }),
 91	);
