 53	export default Backend.make(
 54	  Effect.gen(function* () {
 55	    // Alchemy replaces this flag with true in the deployed bundle. Deployment
 56	    // services exist only in the stack; runtime startup reads actual bindings.
 57	    if (globalThis.__ALCHEMY_RUNTIME__ === true) {
 58	      return {};
 59	    }
 60	    const stage = yield* WebsiteStage;
 61	    const analytics = yield* commonPracticePostHogBindings({ stage });
 62	    const zone = yield* WebsiteZone;
 63	    const base = {
 64	      main: import.meta.url,
 65	      name: BackendWorkerName.make(`common-practice-${stage}-backend`),
 66	      workersDev: stage !== "production",
 67	      dev: { host: "127.0.0.1", port: 3211, strictPort: true },
 68	      compatibility: { date: "2026-09-22", flags: ["nodejs_compat", "enable_request_signal"] },
 69	    };
 70	    const domain = apiHosting(zone);
 71	    if (stage === "dev") {
 72	      return {
 73	        ...base,
 74	        env: {
 75	          COMMON_PRACTICE_STAGE: stage,
 76	          COMMON_PRACTICE_API_URL: Cloudflare.Worker.URL,
 77	          ...analytics,
 78	        },
 79	      };
 80	    }
 81	    const trace = yield* commonPracticeTraceExportProduction;
 82	    return {
 83	      ...base,
 84	      ...domain,
 85	      env: {
 86	        COMMON_PRACTICE_STAGE: stage,
 87	        COMMON_PRACTICE_API_URL: Cloudflare.Worker.URL,
 88	        ...analytics,
 89	      },
 90	      observability: {
 91	        enabled: true,
 92	        logs: {
 93	          enabled: true,
 94	          invocationLogs: true,
 95	          headSamplingRate: 1,
 96	          persist: true,
 97	          destinations: [trace.logsDestinationName],
 98	        },
 99	        traces: {
100	          enabled: true,
101	          headSamplingRate: 1,
102	          persist: true,
103	          destinations: [trace.destinationName],
104	        },
105	      },
106	    };
107	  }),
108	  Effect.gen(function* () {
109	    // Alchemy supplies this instance's scope during native startup. Build the
110	    // registered telemetry and identity there, rather than a temporary scope.
111	    const telemetryServices = yield* Layer.build(
112	      Layer.mergeAll(
113	        Cloudflare.Telemetry(),
114	        Telemetry.layer(Logger.layer([Logger.consoleJson])),
115	      ).pipe(Layer.provideMerge(IsolateIdentityLive)),
116	    );
117	    // Worker.URL is resolved by the provider before upload. Planning cannot
118	    // read that runtime binding; it only registers the native Worker shape.
119	    if ((yield* ALCHEMY_PHASE) === "plan") {
120	      return { fetch: Effect.succeed(HttpServerResponse.empty({ status: 503 })) };
121	    }
122	    const { stage, capture } = yield* WorkerAnalyticsConfig;
123	    const analyticsServices = yield* Layer.build(
124	      backendAnalyticsLayer.pipe(Layer.provide(Layer.succeed(AnalyticsSettings, capture))).pipe(
125	        Layer.provide(
126	          FetchHttpClient.layer.pipe(
127	            Layer.provide(
128	              Layer.succeed(FetchHttpClient.RequestInit, {
129	                credentials: "omit",
130	                redirect: "error",
131	              }),
132	            ),
133	          ),
134	        ),
135	      ),
136	    );
137	    const analytics = yield* BackendAnalytics.pipe(Effect.provideContext(analyticsServices));
138	    const identity = yield* IsolateIdentity.pipe(Effect.provideContext(telemetryServices));
139	    const contentServices = yield* Layer.build(
140	      TrainingLive.pipe(Layer.provide(Layer.succeed(TrainingOutlines, courseOutlines))).pipe(
141	        Layer.provideMerge(
142	          ContentUsageLive.pipe(
143	            Layer.provideMerge(
144	              ContentLive.pipe(Layer.provide(Layer.succeed(ContentSources, bundledPages))).pipe(
145	                Layer.provide(PageRendererLive),
146	              ),
147	            ),
148	          ),
149	        ),
150	      ),
151	    );
152	    const handler = yield* initialiseApiApplication.pipe(Effect.provideContext(contentServices));
153	    return {
154	      fetch: Effect.gen(function* () {
155	        const request = yield* HttpServerRequest.HttpServerRequest;
156	        const isolate = yield* identity.nextRequest;
157	        return yield* observeHostedRequest({
158	          request,
159	          stage,
160	          isolate,
161	          worker: "backend",
162	          operation: observeApiUse({
163	            enabled: Schema.is(CaptureConfig.cases.AnalyticsEnabled)(capture),
164	            operation: handler.http,
165	          }).pipe(Effect.provideService(BackendAnalytics, analytics)),
166	        });
167	      }),
168	    };
169	  }).pipe(
170	    Effect.catchTags({
171	      TrainingSourceError: () =>
172	        Effect.fail(
173	          new Config.ConfigError(
174	            new ConfigProvider.SourceError({ message: "API training outlines are invalid" }),
175	          ),
176	        ),
177	      IllegalArgumentError: () =>
178	        Effect.fail(
179	          new Config.ConfigError(
180	            new ConfigProvider.SourceError({ message: "API image cache configuration is invalid" }),
181	          ),
182	        ),
