 19	
 20	/**
 21	 * Whether a native Web `Headers` and an Effect headers record carry the
 22	 * same entries. Lets {@link makeFetcher} keep forwarding the platform's
 23	 * own request object when `request.modify` left the headers unchanged,
 24	 * and rebuild only when they genuinely differ. Effect header keys are
 25	 * already lowercased and `Headers.get` is case-insensitive, so the
 26	 * comparison needs no normalization.
 27	 */
 28	const sameHeaders = (
 29	  web: Headers,
 30	  eff: Readonly<Record<string, string>>,
 31	): boolean => {
 32	  const keys = Object.keys(eff);
 33	  let webCount = 0;
 34	  for (const _ of web.keys()) {
 35	    webCount++;
 36	    if (webCount > keys.length) return false;
 37	  }
 38	  if (webCount !== keys.length) return false;
 39	  for (const key of keys) {
 40	    if (web.get(key) !== eff[key]) return false;
 41	  }
 42	  return true;
 43	};
