 45	export interface Fetcher {
 46	  raw: cf.Fetcher;
 47	  fetch(
 48	    request: HttpClientRequest.HttpClientRequest,
 49	  ): Effect.Effect<HttpClientResponse.HttpClientResponse, HttpClientError>;
 50	  fetch(
