 87	export const fromCloudflareFetcher = (
 88	  fetcher: cf.Fetcher | globalThis.Fetcher,
 89	): Fetcher => {
 90	  const fetch = (request: Request) =>
 91	    Effect.suspend(() => {
 92	      // Clone per attempt, keeping `request` pristine: the HandlerNotReady
 93	      // retry below re-runs this suspend, and replaying a Request whose body
 94	      // the failed attempt already consumed makes workerd reject with
 95	      // "TypeError: Cannot reconstruct a Request with a used body".
 96	      const attempt = request.clone() as Request;
 97	      return Effect.promise((signal) =>
 98	        (fetcher as globalThis.Fetcher).fetch(attempt, {
 99	          signal: signal,
100	        }),
101	      );
102	    }).pipe(
