    61	 *     // option 2 — call the Effect worker's fetch handler
    62	 *     if (via === "fetch") {
    63	 *       return env.BACKEND.fetch(
    64	 *         `https://backend/?key=${encodeURIComponent(key)}`,
    65	 *       );
    66	 *     }
    67	 *
    68	 *     // option 3 — call an Effect worker RPC method as a Promise
    69	 *     const backend = toRpcAsync<Backend>(env.BACKEND);
    70	 *     const value = await backend.hello(key);
    71	 *     if (value === null) return new Response("Not found", { status: 404 });
    72	 *     return new Response(value);
    73	 *   },
    74	 * };
