 3	import { DomainApiOrigin } from "__SCOPE__/domain/schemas";
 4	import { HttpApiClientLive } from "__SCOPE__/http-api/client/live";
 5	import { Context, Effect, Layer, Predicate, Schema } from "effect";
 6	import type { HttpServerRequest, HttpServerResponse } from "effect/http";
 7	import { HttpClient, HttpServerError } from "effect/http";
 8	import { WebsiteConfiguration } from "../loader";
 9	
10	export class ApiBindingError extends Schema.TaggedError<ApiBindingError>()("ApiBindingError", {
11	  operation: Schema.Literals(["binding", "forward"]),
12	}) {}
13	// Keep the host object's identity; Alchemy owns the conversion into Effect.
14	export const ApiBinding = Schema.declare<Parameters<typeof fromCloudflareFetcher>[0]>(
15	  (value): value is Parameters<typeof fromCloudflareFetcher>[0] =>
16	    Predicate.hasProperty(value, "fetch") &&
17	    Predicate.isFunction(value.fetch) &&
18	    Predicate.hasProperty(value, "connect") &&
19	    Predicate.isFunction(value.connect),
20	);
21	export class WebsiteApi extends Context.Service<
22	  WebsiteApi,
23	  {
24	    readonly forward: (request: HttpServerRequest.HttpServerRequest) => Effect.Effect<HttpServerResponse.HttpServerResponse, ApiBindingError>;
25	    readonly configuration: Effect.Effect<typeof WebsiteConfiguration.Type, ApiBindingError>;
26	  }
27	>()("__SCOPE__/WebsiteApi") {}
28	
29	export const forwardApiRequest = ({ request, binding }: {
30	  readonly request: HttpServerRequest.HttpServerRequest;
31	  readonly binding: typeof ApiBinding.Type;
32	}) => fromCloudflareFetcher(binding).fetch(request).pipe(
33	  // Rejected host Promises are Alchemy defects. Preserve the named transport
34	  // failure without changing cancellation into an ordinary response.
35	  Effect.catchDefect(() => Effect.fail(new ApiBindingError({ operation: "forward" }))),
36	  Effect.mapError(() => new ApiBindingError({ operation: "forward" })),
37	);
38	
39	export const ApiDomainLive = Layer.unwrap(
40	  Effect.gen(function* () {
41	    const api = yield* WebsiteApi;
42	    const transport = toHttpClient({
43	      fetch: (request) => api.forward(request).pipe(
44	        Effect.mapError((cause) => new HttpServerError.HttpServerError({
45	          reason: new HttpServerError.InternalError({ request, cause }),
46	        })),
47	      ),
48	    });
49	    return HttpApiClientLive.pipe(Layer.provide(Layer.succeed(HttpApiClientAddress, { baseUrl: DomainApiOrigin.make("https://backend") }))).pipe(
50	      Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)),
51	    );
52	  }),
53	);
54	export const readWebsiteConfiguration = WebsiteApi.pipe(Effect.flatMap((api) => api.configuration));

