 1	import {
 2	  useAtomInitialValues,
 3	  useAtomSet,
 4	  useAtomValue,
 5	} from "@effect/atom-react";
 6	import type { CalculatorRpcClientError } from "@taxkit/api-rpc/errors";
 7	import type { CalculatorCatalogResponse } from "@taxkit/api-rpc/schemas";
 8	import { AnnualTaxReport } from "@taxkit/rules-au-income-tax/schemas";
 9	import { PayWithholdingsLedger } from "@taxkit/rules-au-pay/schemas";
10	import { Option, Schema } from "effect";
11	import * as Atom from "effect/reactivity/Atom";
12	import { useEffect, useMemo } from "react";
13	
14	import { browserCalculatorToolsAtom } from "./browser-tools.atoms";
15	import { calculationFailureMessage } from "./calculation-failure";
16	import { CalculatorPageView } from "./calculator-page.view";
17	import { calculatorPageAtoms } from "./calculator.atoms";
18	import type { TaxKitWebConfigError } from "./config";
19	import type { WebsiteInputError, WebsiteCalculatorForm } from "./form.boundary";
20	
21	const calculatorPageReport = Schema.Union([
22	  AnnualTaxReport,
23	  PayWithholdingsLedger,
24	]);
25	
26	export const CalculatorPage = ({
27	  calculator,
28	  report,
29	  savedError,
30	  savedForm,
31	}: {
32	  readonly calculator: CalculatorCatalogResponse["calculators"][number];
33	  readonly report: Option.Option<AnnualTaxReport | PayWithholdingsLedger>;
34	  readonly savedError: Option.Option<
35	    CalculatorRpcClientError | TaxKitWebConfigError | WebsiteInputError
36	  >;
37	  readonly savedForm: Option.Option<WebsiteCalculatorForm>;
38	}) => {
39	  const atoms = useMemo(
40	    () => calculatorPageAtoms(calculator.calculatorId),
41	    [calculator.calculatorId]
42	  );
43	  const browserTools = useMemo(
44	    () => browserCalculatorToolsAtom(calculator.calculatorId),
45	    [calculator.calculatorId]
46	  );
47	  useAtomInitialValues(
48	    Option.match(savedForm, {
49	      onNone: () => [],
50	      onSome: (value) => [[atoms.form, value]],
51	    })
52	  );
53	  useAtomInitialValues([
54	    [atoms.savedReport, report],
55	    [
56	      atoms.savedMessage,
57	      savedError.pipe(Option.map(calculationFailureMessage)),
58	    ],
59	  ]);
60	  const controlBrowserTools = useAtomSet(browserTools);
61	  useEffect(() => {
62	    controlBrowserTools("register");
63	    return () => controlBrowserTools(Atom.Interrupt);
64	  }, [controlBrowserTools]);
65	  const view = useAtomValue(atoms.view);
66	  const edit = useAtomSet(atoms.edit);
67	  const submit = useAtomSet(atoms.submit);
68	  const controlCalculation = useAtomSet(atoms.calculation);
69	  useEffect(
70	    () => () => controlCalculation(Atom.Interrupt),
71	    [controlCalculation]
72	  );
73	  return (
74	    <CalculatorPageView
75	      calculatorId={calculator.calculatorId}
76	      form={view.form}
77	      title={calculator.title}
78	      year={calculator.context.taxYear}
79	      busy={view.busy}
80	      message={Option.getOrUndefined(view.message)}
81	      report={view.report.pipe(Option.filter(Schema.is(calculatorPageReport)))}
82	      stale={view.stale}
83	      onEdit={edit}
84	      onCalculate={() => submit("calculate")}
85	    />
86	  );
87	};
