 43	export const readWebsiteConfiguration = Effect.fn("WebsiteApi.configuration")(
 44	  function* ({
 45	    apiUrl,
 46	    websiteUrl,
 47	    capture,
 48	    stage: rawStage,
 49	  }: {
 50	    readonly apiUrl: unknown;
 51	    readonly websiteUrl: unknown;
 52	    readonly capture: unknown;
 53	    readonly stage: unknown;
 54	  }) {
 55	    const bindings = {
 56	      COMMON_PRACTICE_API_URL: apiUrl,
 57	      COMMON_PRACTICE_WEBSITE_URL: websiteUrl,
 58	      COMMON_PRACTICE_POSTHOG_CONFIG: capture,
 59	      COMMON_PRACTICE_STAGE: rawStage,
 60	    };
 61	    // Use the same native Alchemy unwrapping as its Effect Worker host. Only
 62	    // these named settings enter the provider; each Config owns its Schema check.
 63	    const source = ConfigProvider.fromUnknown(bindings);
 64	    const provider = reifyBoundConfigProvider(source, bindings);
 65	    return yield* WebsiteAppConfig.parse(provider);
 66	  },
 67	  Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
 68	);
