 70	// A private binding is an Effect HttpClient transport, rather than a second Content implementation.
 71	export const ApiClientsLive = Layer.unwrap(
 72	  Effect.gen(function* () {
 73	    const api = yield* WebsiteApi;
 74	    const transport = toHttpClient({
 75	      fetch: (request) =>
 76	        api.forward(request).pipe(
 77	          Effect.mapError(
 78	            (cause) =>
 79	              new HttpServerError.HttpServerError({
 80	                reason: new HttpServerError.InternalError({ request, cause }),
 81	              }),
 82	          ),
 83	        ),
 84	    });
 85	    const options = { baseUrl: ApiOrigin.make("https://backend") };
 86	    return Layer.mergeAll(
 87	      contentHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
 88	      trainingHttpClientLayer.pipe(Layer.provide(Layer.succeed(HttpApiAddress, options))),
 89	    ).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)));
 90	  }),
 91	);
