260	export const publishingMiddleware = createMiddleware().server(
261	  ({ request, next: continueRequest }) =>
262	    runForRequest({
263	      effect: Effect.gen(function* () {
264	        const policyRequest: ResponsePolicyRequest = {
265	          adapter: "page",
266	          method: request.method,
267	          pathname: Url.fromString(request.url).pipe(
268	            Result.getSuccess,
269	            Option.map((url) => url.pathname),
270	          ),
271	          indexable: yield* WebsiteApi.pipe(
272	            Effect.flatMap((api) => api.stage),
273	            Effect.map((stage) => stage === "production"),
274	            Effect.orElseSucceed(() => false),
275	          ),
276	        };
277	        const selected = yield* discoveryRepresentation.pipe(
278	          Effect.flatMap((discovery) =>
279	            Option.match(discovery, {
280	              onNone: () => trainingRepresentation,
281	              onSome: Effect.succeedSome,
282	            }),
283	          ),
284	          Effect.flatMap((training) =>
285	            Option.match(training, {
286	              onNone: () => negotiatePage,
287	              onSome: Effect.succeedSome,
288	            }),
289	          ),
290	          Effect.provideService(
291	            HttpServerRequest.HttpServerRequest,
292	            HttpServerRequest.fromWeb(request),
293	          ),
294	        );
295	        if (Option.isSome(selected)) {
296	          return HttpServerResponse.toWeb(
297	            applyResponsePolicy({ request: policyRequest, response: selected.value }),
298	            { withoutBody: request.method === "HEAD" },
299	          );
300	        }
301	        // TanStack permits either a synchronous result or a Promise. tryPromise also
302	        // captures a synchronous throw from the framework callback.
303	        const result = yield* Effect.tryPromise({
304	          try: () => Promise.resolve(continueRequest()),
305	          catch: () => new HostAdapterError({ operation: "framework" }),
306	        });
307	        // Server-function envelopes keep named failures. TanStack's HTML response
308	        // can still say 200, so preserve the request's explicitly selected status.
309	        const requestedStatus = yield* Effect.sync(getResponseStatus);
310	        const status = Match.value(requestedStatus).pipe(
311	          Match.when(200, () => result.response.status),
312	          Match.orElse((value) => value),
313	        );
314	        const policy = responsePolicyHeaders({
315	          ...policyRequest,
316	          privateResponse: hasAppearanceCookie(
317	            yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
318	              Effect.flatMap(readAppearanceCookieHeader),
319	            ),
320	            appearanceOptions,
321	          ),
322	          varyCookie: true,
323	          status,
324	          headers: Headers.fromInput(result.response.headers),
325	          cookies: Cookies.empty,
326	        });
327	        // TanStack tracks the original response stream for SSR cleanup. Preserve its body
328	        // identity here; wrapping it in an Effect Stream would make TanStack close it early.
329	        return yield* Effect.try({
330	          try: () => {
331	            const headers = new globalThis.Headers(result.response.headers);
332	            Function.pipe(
333	              Record.toEntries(policy),
334	              Array.forEach(([name, value]) => {
335	                headers.set(name, value);
336	              }),
337	            );
338	            return {
339	              ...result,
340	              response: new Response(result.response.body, {
341	                status,
342	                statusText: result.response.statusText,
343	                headers,
344	              }),
345	            };
346	          },
347	          catch: () => new HostAdapterError({ operation: "framework" }),
348	        });
349	      }).pipe(observeWebsiteRequest(request)),
350	      signal: request.signal,
351	    }),
352	);
