 27	export const forwardApiRequest = ({
 28	  request,
 29	  binding,
 30	}: {
 31	  readonly request: HttpServerRequest.HttpServerRequest;
 32	  readonly binding: typeof ApiBinding.Type;
 33	}) =>
 34	  fromCloudflareFetcher(binding)
 35	    .fetch(request)
 36	    .pipe(
 37	      // Alchemy reports rejected host Promises as defects. Keep the Website's
 38	      // named transport failure without turning interruption into a response.
 39	      Effect.catchDefect(() => Effect.fail(new ApiBindingError({ operation: "forward" }))),
 40	      Effect.mapError(() => new ApiBindingError({ operation: "forward" })),
 41	    );
