    41	      // reaches the host reporter and native empty response before TanStack can
    42	      // log or serialise an arbitrary Cause as a server-function error.
    43	      Effect.catchCause((cause) =>
    44	        HttpServerError.causeResponse(cause).pipe(
    45	          Effect.flatMap(([response, reportable]) =>
    46	            ErrorReporter.report(reportable).pipe(
    47	              Effect.as(HttpServerResponse.toWeb(response))
    48	            )
