    56	export const loadWebsiteDocsPageServer = () => {
    57	  const request = getRequest();
    58	  const url = new URL(request.url);
    59	  // A fresh native Router signal is private to this request. Only this exact
    60	  // signal bypasses unexpected-error containment; arbitrary defects cannot.
    61	  const missingPage = notFound();
    62	  // SSR reads the real document address. Only the admitted native browser
    63	  // function reads the bounded public header; headers cannot override SSR.
    64	  const rawPath = url.pathname.startsWith(`${WebsiteServerFunctionBase}/`)
    65	    ? request.headers.get("x-taxkit-docs-page")
    66	    : url.pathname;
    67	  return appRuntime.runPromise(
    68	    Schema.decodeUnknownEffect(DocsPublicPagePath)(rawPath).pipe(
    69	      Effect.mapError(
    70	        () =>
    71	          new DocsPageUnavailable({
    72	            message: "The documentation page was not found.",
    73	          })
    74	      ),
    75	      Effect.flatMap((path) =>
    76	        WebsiteServerApplication.pipe(
    77	          Effect.flatMap((application) =>
    78	            Effect.gen(function* () {
