   101	            Effect.flatMap(([response, reportable]) =>
   102	              ErrorReporter.report(reportable).pipe(
   103	                Effect.as(HttpServerResponse.toWeb(response))
   104	              )
   105	            )
   106	          )
   107	      )
   108	    ),
   109	    { signal: request.signal }
   110	  );
   111	};
