   131	            Effect.gen(function* () {
   132	              const settings = yield* application.settings;
   133	              const navigation = yield* application.docsNavigation;
   134	              const results =
   135	                value === "" ? [] : yield* application.searchDocs(value);
   136	              return { navigation, results, settings, term: value };
   137	            })
   138	          )
   139	        )
   140	      ),
   141	      Effect.result,
   142	      Effect.flatMap(Schema.encodeEffect(WebsiteDocsSearchTransport)),
   143	      Effect.orDie,
