   147	            ErrorReporter.report(reportable).pipe(
   148	              Effect.as(HttpServerResponse.toWeb(response))
   149	            )
   150	          )
   151	        )
   152	      )
   153	    ),
   154	    { signal: request.signal }
   155	  );
   156	};
