   640	  group: RpcGroup.RpcGroup<Rpcs>,
   641	  options?: {
   642	    readonly spanPrefix?: string | undefined
   643	    readonly spanAttributes?: Record<string, unknown> | undefined
   644	    readonly generateRequestId?: (() => RequestId) | undefined
   645	    readonly disableTracing?: boolean | undefined
   646	    readonly flatten?: Flatten | undefined
   647	  } | undefined
   648	) => Effect.Effect<
   649	  Flatten extends true ? RpcClient.Flat<Rpcs, RpcClientError> : RpcClient<Rpcs, RpcClientError>,
   650	  never,
   651	  Protocol | Rpc.MiddlewareClient<Rpcs> | Scope.Scope
   652	> = Effect.fnUntraced(function*<Rpcs extends Rpc.Any, const Flatten extends boolean = false>(
   653	  group: RpcGroup.RpcGroup<Rpcs>,
   654	  options?: {
   655	    readonly spanPrefix?: string | undefined
   656	    readonly spanAttributes?: Record<string, unknown> | undefined
   657	    readonly generateRequestId?: (() => RequestId) | undefined
   658	    readonly disableTracing?: boolean | undefined
   659	    readonly flatten?: Flatten | undefined
   660	  } | undefined
   661	) {
   662	  const clientId = clientIdCounter++
   663	  const { codecFor, run, send, supportsAck, supportsTransferables } = yield* Protocol
   664	  const rpcSchemas = makeRpcSchemas(codecFor)
   665	  const decodeDefect = Schema.decodeSync(codecFor(Schema.Defect()))
   666	
   667	  type ClientEntry = {
   668	    readonly rpc: Rpc.AnyWithProps
   669	    readonly context: Context.Context<never>
   670	    readonly schemas: RpcSchemas
   671	  }
   672	  const entries = new Map<RequestId, ClientEntry>()
   673	
   674	  const { client, write } = yield* makeNoSerialization(group, {
   675	    ...options,
   676	    supportsAck,
   677	    onFromClient({ message }) {
   678	      switch (message._tag) {
   679	        case "Request": {
   680	          const rpc = group.requests.get(message.tag)! as any as Rpc.AnyWithProps
   681	          const collector = supportsTransferables ? Transferable.makeCollectorUnsafe() : undefined
   682	
   683	          const fiber = Fiber.getCurrent()!
   684	
   685	          const entry: ClientEntry = {
   686	            rpc,
   687	            context: collector ? Context.add(fiber.context, Transferable.Collector, collector) : fiber.context,
   688	            schemas: rpcSchemas(rpc)
   689	          }
   690	          entries.set(message.id, entry)
   691	
   692	          return entry.schemas.encodePayload(message.payload).pipe(
   693	            Effect.provideContext(entry.context),
   694	            Effect.orDie,
   695	            Effect.flatMap((payload) =>
   696	              send(clientId, {
   697	                ...message,
   698	                id: message.id,
   699	                payload,
   700	                headers: Object.entries(message.headers)
   701	              }, collector && collector.readUnsafe())
   702	            )
   703	          ) as Effect.Effect<void, RpcClientError>
   704	        }
   705	        case "Ack": {
   706	          const entry = entries.get(message.requestId)
   707	          if (!entry) return Effect.void
   708	          return send(clientId, {
   709	            _tag: "Ack",
   710	            requestId: message.requestId
   711	          }) as Effect.Effect<void, RpcClientError>
   712	        }
   713	        case "Interrupt": {
   714	          const entry = entries.get(message.requestId)
   715	          if (!entry) return Effect.void
   716	          entries.delete(message.requestId)
   717	          return send(clientId, {
   718	            _tag: "Interrupt",
   719	            requestId: message.requestId
   720	          }) as Effect.Effect<void, RpcClientError>
   721	        }
   722	        case "Eof": {
   723	          return Effect.void
   724	        }
   725	      }
   726	    }
   727	  })
   728	
   729	  yield* run(clientId, (message) => {
   730	    switch (message._tag) {
   731	      case "Chunk": {
   732	        const requestId = RequestId(message.requestId)
   733	        const entry = entries.get(requestId)
   734	        if (!entry || Option.isNone(entry.schemas.decodeChunk)) return Effect.void
   735	        return entry.schemas.decodeChunk.value(message.values).pipe(
   736	          Effect.provideContext(entry.context),
   737	          Effect.orDie,
   738	          Effect.flatMap((chunk) =>
   739	            write({ _tag: "Chunk", clientId: 0, requestId: RequestId(message.requestId), values: chunk })
   740	          ),
   741	          Effect.onError((cause) =>
   742	            write({
   743	              _tag: "Exit",
   744	              clientId: 0,
   745	              requestId: RequestId(message.requestId),
   746	              exit: Exit.failCause(cause)
   747	            })
   748	          )
   749	        ) as Effect.Effect<void>
   750	      }
   751	      case "Exit": {
   752	        const requestId = RequestId(message.requestId)
   753	        const entry = entries.get(requestId)
   754	        if (!entry) return Effect.void
   755	        entries.delete(requestId)
   756	        return entry.schemas.decodeExit(message.exit).pipe(
   757	          Effect.provideContext(entry.context),
   758	          Effect.orDie,
   759	          Effect.matchCauseEffect({
   760	            onSuccess: (exit) => write({ _tag: "Exit", clientId: 0, requestId, exit }),
   761	            onFailure: (cause) => write({ _tag: "Exit", clientId: 0, requestId, exit: Exit.failCause(cause) })
   762	          })
   763	        ) as Effect.Effect<void>
   764	      }
   765	      case "Defect": {
   766	        return write({ _tag: "Defect", clientId: 0, defect: decodeDefect(message.defect as any) })
   767	      }
   768	      case "ClientProtocolError": {
   769	        const exit = Exit.fail(message.error)
   770	        return Effect.forEach(
   771	          entries.keys(),
   772	          (requestId) => write({ _tag: "Exit", clientId: 0, requestId, exit: exit as any })
   773	        )
   774	      }
   775	      default: {
   776	        return Effect.void
   777	      }
   778	    }
   779	  }).pipe(
   780	    Effect.catchCause(Effect.logError),
   781	    Effect.interruptible,
   782	    Effect.forkScoped
   783	  )
   784	
   785	  return client
   786	})
   787	
   788	interface RpcSchemas {
   789	  readonly decodeChunk: Option.Option<
   790	    (chunk: ReadonlyArray<unknown>) => Effect.Effect<NonEmptyReadonlyArray<any>, Schema.SchemaError, unknown>
   870	 * receive loop and sending encoded client messages.
   871	 *
   872	 * **When to use**
   873	 *
   874	 * Use to provide the transport boundary for RPC clients over HTTP, WebSocket,
   875	 * workers, sockets, or custom protocols.
   876	 *
   877	 * @stability unstable
   878	 * @category services
   879	 * @since 4.0.0
   880	 */
   881	export class Protocol extends Context.Service<Protocol, {
   882	  readonly run: (
   883	    clientId: number,
   884	    f: (data: FromServerEncoded) => Effect.Effect<void>
   885	  ) => Effect.Effect<never>
   886	  readonly send: (
   887	    clientId: number,
   888	    request: FromClientEncoded,
   889	    transferables?: ReadonlyArray<globalThis.Transferable>
   890	  ) => Effect.Effect<void, RpcClientError>
   891	  readonly supportsAck: boolean
   892	  readonly supportsTransferables: boolean
   893	  /**
   894	   * Builds the codec that fills the `unknown` holes of the protocol messages,
   895	   * re-passed from the `RpcSerialization` backing this transport.
   896	   */
   897	  readonly codecFor: RpcSerialization.CodecFor
   898	}>()("effect/rpc/RpcClient/Protocol") {
   899	  /**
   900	   * Creates a client protocol service from the supplied RPC request runner.
   901	   *
   902	   * @stability unstable
   903	   * @since 4.0.0
   904	   */
   905	  static make = withRunClient
   906	}
   907	
   908	/**
   909	 * Creates a client `Protocol` that sends each RPC request through the supplied
   910	 * `HttpClient` and decodes responses with the current `RpcSerialization`.
   911	 *
   912	 * @stability unstable
   913	 * @category protocols
   914	 * @since 4.0.0
   915	 */
   916	export const makeProtocolHttp = (client: HttpClient.HttpClient): Effect.Effect<
   917	  Protocol["Service"],
   918	  never,
   919	  RpcSerialization.RpcSerialization
   920	> =>
   921	  Protocol.make(Effect.fnUntraced(function*(writeResponse) {
   922	    const serialization = yield* RpcSerialization.RpcSerialization
   923	    const isFramed = serialization.includesFraming
   924	    const httpClientError = (cause: any) =>
   925	      new RpcClientError({
   926	        reason: HttpClientErrorSchema.fromHttpClientError(cause)
   927	      })
   928	    const protocolDefect = (message: string, cause: unknown) =>
   929	      new RpcClientError({
   930	        reason: new RpcClientDefect({ message, cause })
   931	      })
   932	    const emptyResponseError = (request: FromClientEncoded) =>
   933	      protocolDefect("Received empty HTTP response from RPC server", request)
   934	    const incompleteResponseError = (request: FromClientEncoded) =>
   935	      protocolDefect("HTTP response ended before RPC request completed", request)
   936	
   937	    const send = Effect.fnUntraced(function*(clientId: number, request: FromClientEncoded) {
   938	      if (request._tag !== "Request") {
   939	        return
   940	      }
