 3	  InvalidContentResponseError,
 4	} from "@common-practice/content/errors";
 5	import { checkedPageOperation } from "@common-practice/content/response-check";
 6	import { Content, contentClientTimeout } from "@common-practice/content/service";
 7	import * as Effect from "effect/Effect";
 8	import * as Layer from "effect/Layer";
 9	import * as Match from "effect/Match";
10	import type * as HttpClientError from "effect/http/HttpClientError";
11	import * as HttpApiClient from "effect/http-api/HttpApiClient";
12	import { ContentApi } from "./api";
13	import { HttpApiAddress } from "./config";
14	
15	const httpFailure = (
16	  operation: "get-page" | "list-pages",
17	  error: HttpClientError.HttpClientError,
18	) =>
19	  Match.value(error.reason).pipe(
20	    Match.tag("DecodeError", () => new InvalidContentResponseError({ operation })),
21	    Match.tag("EmptyBodyError", () => new InvalidContentResponseError({ operation })),
22	    Match.orElse(() => new ContentUnavailableError({ operation })),
23	  );
24	
25	export const contentHttpClientLayer = Layer.effect(
26	  Content,
27	  Effect.gen(function* () {
28	    const options = yield* HttpApiAddress;
29	    const client = yield* HttpApiClient.make(ContentApi, options);
30	    return Content.of({
31	      listPages: client.pages.listPages({}).pipe(
32	        Effect.timeoutOrElse({
33	          duration: contentClientTimeout,
34	          orElse: () => Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
35	        }),
36	        Effect.catchTags({
37	          HttpClientError: (error) => Effect.fail(httpFailure("list-pages", error)),
38	          SchemaError: () =>
39	            Effect.fail(new InvalidContentResponseError({ operation: "list-pages" })),
40	        }),
41	        Effect.withSpan("Content.listPages"),
42	      ),
43	      getPage: checkedPageOperation({
44	        getPage: (request) =>
45	          client.pages
46	            .getPage({
47	              params: { id: request.id },
48	              query: { format: request.format },
49	            })
50	            .pipe(
51	              Effect.timeoutOrElse({
52	                duration: contentClientTimeout,
53	                orElse: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
54	              }),
55	              Effect.catchTags({
56	                HttpClientError: (error) => Effect.fail(httpFailure("get-page", error)),
57	                SchemaError: () =>
58	                  Effect.fail(new InvalidContentResponseError({ operation: "get-page" })),
59	              }),
60	            ),
61	      }),
62	    });
63	  }),
64	);

