 7	import type * as HttpServerRequest from "effect/http/HttpServerRequest";
 8	import { DeploymentStageConfig } from "@common-practice/infrastructure/config";
 9	import { ApiBinding, forwardApiRequest, readWebsiteConfiguration } from "./binding.adapter.layer";
10	import { ApiBindingError } from "./errors";
11	import { WebsiteApi } from "./service";
12	
13	// Alchemy's TanStack pattern: import the host normally; read env during operations.
14	const bindings = Effect.try({
15	  try: () => Cloudflare.env,
16	  catch: () => new ApiBindingError({ operation: "binding" }),
17	});
18	
19	export const WebsiteApiLive = Layer.effect(
20	  WebsiteApi,
21	  Effect.gen(function* () {
22	    const configuration = yield* bindings.pipe(
23	      Effect.flatMap((env) =>
24	        readWebsiteConfiguration({
25	          apiUrl: env.COMMON_PRACTICE_API_URL,
26	          websiteUrl: env.COMMON_PRACTICE_WEBSITE_URL,
27	          capture: env.COMMON_PRACTICE_POSTHOG_CONFIG,
28	          stage: env.COMMON_PRACTICE_STAGE,
29	        }),
30	      ),
31	      Effect.result,
32	    );
33	    const stage = yield* bindings.pipe(
34	      Effect.flatMap((env) => {
35	        const selected = { COMMON_PRACTICE_STAGE: env.COMMON_PRACTICE_STAGE };
36	        const source = ConfigProvider.fromUnknown(selected);
37	        const provider = reifyBoundConfigProvider(source, selected);
38	        return DeploymentStageConfig.parse(provider);
39	      }),
40	      Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
41	      Effect.result,
42	    );
43	    // Keep checked settings or named failures for this Layer's lifetime.
44	    return WebsiteApi.of({
45	      forward: Effect.fn("WebsiteApi.forward")(function* (
46	        request: HttpServerRequest.HttpServerRequest,
47	      ) {
48	        const env = yield* bindings;
49	        const binding = yield* Schema.decodeUnknownEffect(ApiBinding)(env.BACKEND).pipe(
50	          Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
51	        );
52	        return yield* forwardApiRequest({ request, binding });
53	      }),
54	      configuration: Effect.fromResult(configuration),
55	      stage: Effect.fromResult(stage),
56	    });
57	  }),
58	);

