 77	export const appearanceAtoms = makeAppearanceModel(browserRuntime);
 78	export const appearanceControlAtom = browserRuntime
 79	  .fn(
 80	    Effect.fn("Browser.chooseAppearanceFromControl")(function* (input: AppearanceControlInput) {
 81	      // Retain the scheduler yield so Atom tracks a child before input failure.
 82	      yield* Effect.yieldNow;
 83	      yield* appearanceAtoms.change(yield* readAppearanceControlInput(input));
 84	    }),
 85	    { concurrent: true },
 86	  )
 87	  .pipe(Atom.keepAlive);
 88	export const webMcpAtom = browserRuntime.atom((get) =>
 89	  Layer.build(
 90	    Layer.unwrap(
 91	      get.result(checkedBrowserConfigAtom, { suspendOnWaiting: true }).pipe(
 92	        Effect.map((config) =>
 93	          Layer.mergeAll(
 94	            ModelContextHostLive.pipe(
 95	              Layer.provide(Layer.succeed(WebsiteIdentity, { origin: config.websiteOrigin })),
 96	            ),
 97	            ContentToolHandlers.pipe(
 98	              Layer.provide(
 99	                Layer.mergeAll(
100	                  contentHttpClientLayer.pipe(
101	                    Layer.provide(Layer.succeed(HttpApiAddress, { baseUrl: config.apiOrigin })),
102	                  ),
103	                  trainingHttpClientLayer.pipe(
104	                    Layer.provide(Layer.succeed(HttpApiAddress, { baseUrl: config.apiOrigin })),
105	                  ),
106	                ).pipe(
107	                  Layer.provide(
108	                    FetchHttpClient.layer.pipe(
109	                      Layer.provide(
110	                        Layer.succeed(FetchHttpClient.RequestInit, {
111	                          credentials: "omit",
112	                          redirect: "error",
113	                        }),
114	                      ),
115	                    ),
116	                  ),
117	                ),
118	              ),
119	            ),
120	          ),
121	        ),
122	      ),
123	    ),
124	  ).pipe(Effect.flatMap((services) => registerWebMcpTools.pipe(Effect.provide(services)))),
125	);
126	export const pageViewAtom = browserRuntime.fn(
127	  Effect.fn("Browser.recordPageView")((input: PageView) =>
128	    Effect.gen(function* () {
129	      const analytics = yield* BrowserAnalytics;
130	      yield* analytics.recordPageView(input);
131	    }).pipe(withBrowserAnalytics),
132	  ),
133	  { concurrent: true },
134	);
135	export const navigationAtom = browserRuntime.fn(
136	  Effect.fn("Browser.recordNavigation")((input: NavigationUse) =>
137	    Effect.gen(function* () {
138	      const analytics = yield* BrowserAnalytics;
139	      yield* analytics.recordNavigation(input);
140	    }).pipe(withBrowserAnalytics),
141	  ),
142	  { concurrent: true },
143	);

