 7	
 8	export const CalculatorHostMode = Schema.Literals(["edge", "local-emulator"]);
 9	export type CalculatorHostMode = typeof CalculatorHostMode.Type;
10	
11	// Only direct Cloudflare edge requests supply this identity. Same-zone Worker
12	// subrequests can alter x-real-ip; reject that path instead of trusting it.
13	// Website forwarding uses the separate private binding method, never a header.
14	export const calculatorEdgeRateKey = (
15	  headers: Headers.Headers
16	): Option.Option<typeof CalculatorClientRateKey.Type> =>
17	  Option.isSome(Headers.get(headers, "cf-worker"))
18	    ? Option.none()
19	    : Headers.get(headers, "cf-connecting-ip").pipe(
20	        Option.flatMap(Schema.decodeUnknownOption(CalculatorClientRateKey))
21	      );

